pub fn language_spec_for_target(target: RenderTarget) -> Rc<LanguageSpec> {
    match target {
    RenderTarget::Rust => rust_spec(),
    RenderTarget::Go => go_spec(),
    RenderTarget::Python => python_spec(),
    RenderTarget::Dag => rust_spec(),
}
}

pub fn target_keyword(target: RenderTarget, key: String) -> String {
    match target {
    RenderTarget::Rust => match v2_rt::lookup(&rust_keywords(), key.clone()) {
    Some(kw) => kw.clone(),
    None => key.clone(),
},
    RenderTarget::Go => match v2_rt::lookup(&go_keywords(), key.clone()) {
    Some(kw) => kw.clone(),
    None => key.clone(),
},
    RenderTarget::Python => match v2_rt::lookup(&python_keywords(), key.clone()) {
    Some(kw) => kw.clone(),
    None => key.clone(),
},
    RenderTarget::Dag => key.clone(),
}
}

pub fn target_operators(target: RenderTarget) -> Rc<Vec<Rc<OperatorSpec>>> {
    match target {
    RenderTarget::Rust => rust_operators(),
    RenderTarget::Python => python_operators(),
    RenderTarget::Go => go_operators(),
    RenderTarget::Dag => dag_operators(),
}
}

pub fn binop_symbol(target: RenderTarget, op: BinOp, algebra_field: Option<String>) -> Option<String> {
    {
        let ops = target_operators(target);
let op_matching = Rc::new({ let mut __result = Vec::new(); for spec in ops.iter().cloned() { if match spec.binop.clone() {
    Some(b) => (b.clone() == op.clone()),
    None => false,
} { __result.push(spec); } } __result });
let specific = match algebra_field {
    Some(af) => Rc::new({ let mut __result = Vec::new(); for spec in op_matching.clone().iter().cloned() { if match spec.algebra_field.clone() {
    Some(sf) => (sf.clone().as_str() == af.clone().as_str()),
    _ => false,
} { __result.push(spec); } } __result }).first().cloned(),
    None => None,
};
let result = match specific.clone() {
    Some(_) => specific.clone(),
    None => Rc::new({ let mut __result = Vec::new(); for spec in op_matching.clone().iter().cloned() { if (spec.algebra_field.clone() == None) { __result.push(spec); } } __result }).first().cloned(),
};
match result {
    Some(spec) => Some(spec.symbol.clone()),
    None => None,
}
}
}

pub fn is_string_like(target: RenderTarget, name: String) -> bool {
    match target {
    RenderTarget::Rust => { let mut __found = false; for t in rust_string_types().iter().cloned() { if (t.clone().as_str() == name.clone().as_str()) { __found = true; break; } } __found },
    RenderTarget::Go => { let mut __found = false; for t in go_string_types().iter().cloned() { if (t.clone().as_str() == name.clone().as_str()) { __found = true; break; } } __found },
    RenderTarget::Python => { let mut __found = false; for t in python_string_types().iter().cloned() { if (t.clone().as_str() == name.clone().as_str()) { __found = true; break; } } __found },
    RenderTarget::Dag => false,
}
}

